#!/usr/bin/env python3
import sys, json, re, zipfile, shutil, os

TEMPLATE = "inputs/offer_letter_template.docx"
DATA = "inputs/employee_data.json"
OUT = "output/offer_letter_filled.docx"

PARTS = ["word/document.xml", "word/header1.xml", "word/footer1.xml"]

def fail(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(1)

with open(DATA, encoding="utf-8") as f:
    data = json.load(f)

z = zipfile.ZipFile(TEMPLATE)
names = z.namelist()
parts = {n: z.read(n).decode("utf-8") for n in PARTS if n in names}
raw = {n: z.read(n) for n in names}

# --- Discover declared placeholder tokens across parts (merging runs per paragraph) ---
TOKEN_RE = re.compile(r"\{\{([A-Z0-9_]+)\}\}")
COND_OPEN = "IF_RELOCATION"
COND_CLOSE = "END_IF_RELOCATION"

def para_text(p):
    return "".join(re.findall(r"<w:t[^>]*>(.*?)</w:t>", p, re.S))

declared = set()
for n, xml in parts.items():
    for p in re.findall(r"<w:p[ >].*?</w:p>", xml, re.S):
        for t in TOKEN_RE.findall(para_text(p)):
            declared.add(t)

# Required substitution fields (exclude control tokens)
value_fields = {t for t in declared if t not in (COND_OPEN, COND_CLOSE)}

# --- Conditional governance ---
conditional_present = COND_OPEN in declared or COND_CLOSE in declared
keep_cond = False
if conditional_present:
    if "RELOCATION_PACKAGE" not in data:
        fail("Conditional IF_RELOCATION present but required field RELOCATION_PACKAGE is missing.")
    gov = data["RELOCATION_PACKAGE"]
    if not isinstance(gov, str):
        fail("RELOCATION_PACKAGE must be a string.")
    keep_cond = (gov.strip() == "Yes")

# If conditional removes content, the tokens inside it are not required.
# Determine which value fields are inside the conditional (per paragraph span).
cond_inner_fields = set()
for n, xml in parts.items():
    for p in re.findall(r"<w:p[ >].*?</w:p>", xml, re.S):
        txt = para_text(p)
        mo = re.search(re.escape("{{"+COND_OPEN+"}}") + r"(.*?)" + re.escape("{{"+COND_CLOSE+"}}"), txt, re.S)
        if mo:
            for t in TOKEN_RE.findall(mo.group(1)):
                cond_inner_fields.add(t)

required = set(value_fields)
if not keep_cond:
    required -= cond_inner_fields

missing = sorted(f for f in required if f not in data)
if missing:
    fail("Missing required field(s): " + ", ".join(missing))

def resolve(token):
    if token not in data:
        return None
    v = data[token]
    if v is None:
        return None
    return str(v)

def process_paragraph(p):
    txt = para_text(p)
    if "{{" not in txt:
        return p
    # Apply conditional first (single-paragraph only)
    def cond_sub(m):
        return m.group(1) if keep_cond else ""
    newtxt = re.sub(re.escape("{{"+COND_OPEN+"}}") + r"(.*?)" + re.escape("{{"+COND_CLOSE+"}}"),
                    cond_sub, txt, flags=re.S)
    # Replace value tokens
    def val_sub(m):
        tok = m.group(1)
        if tok in (COND_OPEN, COND_CLOSE):
            return m.group(0)  # leave stray control tokens untouched
        r = resolve(tok)
        return r if r is not None else m.group(0)
    newtxt = TOKEN_RE.sub(val_sub, newtxt)
    if newtxt == txt:
        return p
    # Rebuild: put newtxt into first <w:t>, empty the rest.
    runs = list(re.finditer(r"(<w:t[^>]*>)(.*?)(</w:t>)", p, re.S))
    if not runs:
        return p
    # XML-escape content
    def esc(s):
        return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
    out = []
    last = 0
    for i, mt in enumerate(runs):
        out.append(p[last:mt.start()])
        open_tag = mt.group(1)
        if i == 0:
            # ensure xml:space preserve so leading/trailing spaces kept
            if "xml:space" not in open_tag:
                open_tag = open_tag[:-1] + ' xml:space="preserve">'
            out.append(open_tag + esc(newtxt) + mt.group(3))
        else:
            out.append(mt.group(1) + mt.group(3))
        last = mt.end()
    out.append(p[last:])
    return "".join(out)

for n in list(parts.keys()):
    xml = parts[n]
    parts[n] = re.sub(r"<w:p[ >].*?</w:p>", lambda m: process_paragraph(m.group(0)), xml, flags=re.S)
    # sanity: no leftover tokens
    leftover = TOKEN_RE.findall(re.sub(r"<[^>]+>","", parts[n]))
    if leftover:
        fail("Unresolved tokens remain in %s: %s" % (n, sorted(set(leftover))))

os.makedirs("output", exist_ok=True)
with zipfile.ZipFile(OUT, "w", zipfile.ZIP_DEFLATED) as zo:
    for n in names:
        if n in parts:
            zo.writestr(n, parts[n].encode("utf-8"))
        else:
            zo.writestr(n, raw[n])

print("Conditional present:", conditional_present, "| keep_cond:", keep_cond)
print("Declared value fields:", sorted(value_fields))
print("OK ->", OUT)
